37	using namespace vortex;
38	
39	static void show_usage() {
40	   std::cout << "Usage: [-s: stats] [-d: debug-mode] [-p <port>: RBB port] [-V: verbose debug logging] [-h: help] <program>" << std::endl;
41	}
42	
43	bool showStats = false;
44	bool debug_mode = false;
45	bool debug_verbose = false;  // Verbose debug module logging
46	uint16_t rbb_port = 9823;    // Default OpenOCD remote bitbang port
47	const char* program = nullptr;
48	
49	static void parse_args(int argc, char **argv) {
50	  	int c;
51	  	while ((c = getopt(argc, argv, "shdp:V")) != -1) {
52	    	switch (c) {
53	      case 's':
54	        showStats = true;
55	        break;
56	      case 'd':
57	        debug_mode = true;
58	        break;
59	      case 'p':
60	        rbb_port = static_cast<uint16_t>(atoi(optarg));
61	        break;
62	      case 'V':
63	        debug_verbose = true;
64	        break;
65	    	case 'h':
66	      	show_usage();
67	      	exit(0);
68	    		break;
69	    	default:
70	      	show_usage();
71	      	exit(-1);
72	    	}
73		}
74	
75		if (optind < argc) {
76			program = argv[optind];
77	    if (!debug_mode) {
78	      std::cout << "Running " << program << "..." << std::endl;
79	    }
80		} else {
81			show_usage();
82	    exit(-1);
83		}
84	}
85	
86	int main(int argc, char **argv) {
87	  int exitcode = 0;
88	
89	  parse_args(argc, argv);
90	
91	  {
92	    // create memory module
93	    RAM ram(0, VX_VM_PAGE_SIZE);
94	
95	    // create processor
96	    Processor processor;
97	
98	    // attach memory module
99	    processor.attach_ram(&ram);
100	
101		  // setup base DCRs
102	    const uint64_t startup_addr = 0x80000000;  // flat-image (vxbin/bin/hex) load address; the ELF path uses img.entry
103	    processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR0, startup_addr & 0xffffffff);
104	  #if (VX_CFG_XLEN == 64)
105	    processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR1, startup_addr >> 32);
106	  #endif
107	    processor.dcr_write(VX_DCR_KMU_STARTUP_ARG0, 0);
108	    processor.dcr_write(VX_DCR_KMU_STARTUP_ARG1, 0);
109	    processor.dcr_write(VX_DCR_KMU_GRID_DIM_X,   1);
110	    processor.dcr_write(VX_DCR_KMU_GRID_DIM_Y,   1);
111	    processor.dcr_write(VX_DCR_KMU_GRID_DIM_Z,   1);
112	    processor.dcr_write(VX_DCR_KMU_BLOCK_DIM_X,  1);
113	    processor.dcr_write(VX_DCR_KMU_BLOCK_DIM_Y,  1);
114	    processor.dcr_write(VX_DCR_KMU_BLOCK_DIM_Z,  1);
115	    processor.dcr_write(VX_DCR_KMU_LMEM_SIZE,    0);
116	    processor.dcr_write(VX_DCR_KMU_BLOCK_SIZE,   1);
117	    processor.dcr_write(VX_DCR_KMU_WARP_STEP_X,  VX_CFG_NUM_THREADS);
118	    processor.dcr_write(VX_DCR_KMU_WARP_STEP_Y,  0);
119	    processor.dcr_write(VX_DCR_KMU_WARP_STEP_Z,  0);
120	    processor.dcr_write(VX_DCR_KMU_CLUSTER_DIM_X, 1);
121	    processor.dcr_write(VX_DCR_KMU_CLUSTER_DIM_Y, 1);
122	    processor.dcr_write(VX_DCR_KMU_CLUSTER_DIM_Z, 1);
123	
124	    // load program
125	    HostMonitor monitor;
126	    {
127	      std::string program_ext(fileExtension(program));
128	      if (isElfFile(program)) {
129	        // ELF executables (e.g. upstream riscv-tests) carry their own
130	        // entry point and the HTIF `tohost` pass/fail symbol.
131	        ElfImage img;
132	        if (!loadElfImage(program, ram, &img))
133	          return -1;
134	        monitor.attach(img);
135	        processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR0, img.entry & 0xffffffff);
136	      #if (VX_CFG_XLEN == 64)
137	        processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR1, img.entry >> 32);
138	      #endif
139	      } else if (program_ext == "vxbin") {
140	        ram.loadVxImage(program);
141	      } else if (program_ext == "bin") {
142	        ram.loadBinImage(program, startup_addr);
143	      } else if (program_ext == "hex") {
144	        ram.loadHexImage(program);
145	      } else {
146	        std::cerr << "Error: only ELF, *.vxbin, *.bin or *.hex images supported." << std::endl;
147	        return -1;
148	      }
149	    }
150	  #ifndef NDEBUG
151	    std::cout << "[VXDRV] START: program=" << program << std::endl;
152	  #endif
153	
154	    if (debug_mode) {
155	      // Debug mode: run RBB server in a tick loop until OpenOCD disconnects
156	      // and the program has completed naturally.
157	      std::cout << "[DEBUG] Starting debug mode on port " << rbb_port << std::endl;
158	
159	      DebugModule::set_verbose_logging(debug_verbose);
160	
161	      // Reset processor and kick the KMU. In normal run() mode these are
162	      // both done at the top of run(); debug mode replaces run() with its
163	      // own tick loop, so it must do them explicitly.
164	      processor.reset();
165	      processor.start_kmu();
166	
167	      Core* core = processor.get_first_core();
168	      if (core == nullptr) {
169	        std::cerr << "[DEBUG] no cores configured" << std::endl;
170	        return -1;
171	      }
172	
173	      // Prime warp 0's PC to the configured startup address. The Scheduler
174	      // sets warp PC only when the KMU dispatches a CTA, so for DTM debug
175	      // we initialize it directly before any cycle has run. The DCR-driven
176	      // dispatch path still works on resume via normal KMU scheduling.
177	      core->dtm_set_pc(0, static_cast<vortex::Word>(startup_addr));
178	
179	      DebugModule dm(core, &ram);
180	
181	      // Halt the hart at startup so the debugger can control execution.
182	      // Set DPC to the initial PC so the first RR of DPC reads correctly.
183	      vortex::Word initial_pc = core->dtm_get_pc(0);
184	      dm.set_debug_mode_enabled(true);
185	      dm.direct_write_register(0x7B1, initial_pc);
186	      dm.halt_hart(0);
187	
188	      jtag_dtm_t dtm(&dm);
189	      remote_bitbang_t rbb(rbb_port, &dtm);
190	
191	      std::cout << "[DEBUG] Remote bitbang server ready. Waiting for OpenOCD connection..." << std::endl;
192	
193	      bool program_completed_notified = false;
194	      bool ever_ran = false;
195	      while (true) {
196	        // Only advance the simulator while the hart is not halted by DTM;
197	        // honoring DM's halt state at the tick boundary implements halt/resume.
198	        if (!dm.hart_is_halted()) {
199	          SimPlatform::instance().tick();
200	          if (processor.any_running()) {
201	            ever_ran = true;
202	          }
203	        }
204	        rbb.tick();
205	
206	        // Once the program has actually started, detect natural completion
207	        // (no clusters running and no in-flight channel packets) and notify
208	        // DebugModule once. The debugger can still resume / inspect after.
209	        if (ever_ran && !program_completed_notified && !processor.any_running()) {
210	          dm.notify_program_completed(core->dtm_get_pc(0));
211	          program_completed_notified = true;
212	        }
213	      }
214	      // Unreachable in practice; debug mode is a long-running session.
215	    } else if (monitor.enabled()) {
216	      // HTIF mode: tick until the test writes its `tohost` word, then
217	      // take the exit code from there. Used by upstream riscv-tests/isa.
218	      while (processor.cycle()) {
219	        if (monitor.tick(ram))
220	          break;
221	      }
222	      exitcode = monitor.exit_code();
223	    } else {
224	      // Drain the COUT ring every cycle; standalone simx has no host runtime,
225	      // so vx_printf output would stall on a full ring without this.
226	      // Constructing CoutDrainer with `ram` resets the ring on entry.
227	      CoutDrainer cout(ram);
228	      while (processor.cycle()) {
229	        cout.tick();
230	      }
231	      cout.tick(); // flush any remaining bytes
232	
233	      // flush GPU caches before reading back results
234	      {
235	        uint32_t dummy;
236	        for (uint32_t cid = 0; cid < VX_CFG_NUM_CORES * VX_CFG_NUM_CLUSTERS; ++cid) {
237	          processor.dcr_read(VX_DCR_BASE_CACHE_FLUSH, cid, &dummy);
238	        }
239	      }
240	
241	      // read exitcode from @MPM.1
242	      ram.read(&exitcode, VX_MEM_IO_EXIT_CODE, 4);
243	    }
244	  }
245	
246	  return exitcode;
247	}
