289	  if (is_kmu_dcr) {
290	    kmu_->dcr_write(addr, value);
291	    return 0;
292	  }
293	  for (auto& cluster : clusters_) {
294	    int ret = cluster->dcr_write(addr, value);
295	    if (ret != 0)
296	      return ret;
297	  }
298	  return 0;
