56	class Core::Impl {
57	public:
58	  Impl(const SimContext& ctx, Core* simobject)
59	    : simobject_(simobject)
60	    , sequencers_(VX_CFG_NUM_WARPS)
61	    , mpm_class_(0)
62	    , ibuffers_(VX_CFG_NUM_WARPS)
63	    , operands_(VX_CFG_ISSUE_WIDTH)
64	    , dispatchers_((uint32_t)FUType::Count)
65	    , func_units_((uint32_t)FUType::Count)
66	    , lmem_switch_(VX_CFG_NUM_LSU_BLOCKS)
67	    , mem_coalescers_(VX_CFG_NUM_LSU_BLOCKS)
68	    , fetch_latch_(ctx, "fetch_latch", 2, 2)
69	    , decode_latch_(ctx, "decode_latch", 1, 2)
70	    , pending_icache_(VX_CFG_NUM_WARPS)
71	    , commit_arbs_(VX_CFG_ISSUE_WIDTH)
72	    , ibuffer_arbs_(VX_CFG_ISSUE_WIDTH, {ArbiterType::GTO, PER_ISSUE_WARPS})
73	    , fu_locked_(VX_CFG_ISSUE_WIDTH, BitVector<>((uint32_t)FUType::Count, 0))
74	    , fu_credits_(VX_CFG_ISSUE_WIDTH, std::vector<uint32_t>((uint32_t)FUType::Count, 0))
75	    , ibuf_inflight_(VX_CFG_NUM_WARPS, 0)
76	  {
77	    const std::string& name = simobject_->name();
78	    char sname[100];
79	
80	    // create scheduler (SimObject) — also creates the CTA dispatcher.
81	    snprintf(sname, 100, "%s-scheduler", name.c_str());
82	    scheduler_ = SimPlatform::instance().create_object<Scheduler>(sname, simobject_);
83	
84	    // create decoder (SimObject)
85	    snprintf(sname, 100, "%s-decoder", name.c_str());
86	    decoder_ = SimPlatform::instance().create_object<Decoder>(sname, instr_pool_);
87	
88	  #ifdef VX_CFG_EXT_C_ENABLE
89	    // create RVC fetch decompressor (SimObject) — owns per-warp half-word
90	    // buffer + refetch queue. Resets via SimObject::on_reset.
91	    snprintf(sname, 100, "%s-decompressor", name.c_str());
92	    decompressor_ = SimPlatform::instance().create_object<Decompressor>(sname, VX_CFG_NUM_WARPS);
93	  #endif
94	
95	    // create scoreboard (SimObject)
96	    snprintf(sname, 100, "%s-scoreboard", name.c_str());
97	    scoreboard_ = SimPlatform::instance().create_object<Scoreboard>(sname);
98	
99	    // create per-warp sequencers (SimObject)
100	    for (uint32_t w = 0; w < VX_CFG_NUM_WARPS; ++w) {
101	      snprintf(sname, 100, "%s-sequencer%d", name.c_str(), w);
102	      sequencers_.at(w) = SimPlatform::instance().create_object<Sequencer>(sname, simobject_, instr_pool_);
103	    }
104	
105	    // create operands
106	    for (uint32_t iw = 0; iw < VX_CFG_ISSUE_WIDTH; ++iw) {
107	      snprintf(sname, 100, "%s-operand%d", name.c_str(), iw);
108	      operands_.at(iw) = Operands::Create(sname, simobject_);
109	    }
110	
111	    // create ibuffers
112	    for (uint32_t i = 0; i < ibuffers_.size(); ++i) {
113	      snprintf(sname, 100, "%s-ibuffer%d", name.c_str(), i);
114	      ibuffers_.at(i) = TFifo<instr_trace_t*>::Create(sname, 1, VX_CFG_IBUF_SIZE);
115	    }
116	
117	    // create the memory coalescer
118	    for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
119	      snprintf(sname, 100, "%s-coalescer%d", name.c_str(), b);
120	      mem_coalescers_.at(b) = MemCoalescer::Create(sname, LSU_CHANNELS, DCACHE_CHANNELS, DCACHE_WORD_SIZE, LSU_QUEUE_OUT_SIZE, 1);
121	    }
122	
123	    // create local memory.
124	    snprintf(sname, 100, "%s-lmem", name.c_str());
125	    uint32_t lmem_num_reqs = LSU_NUM_REQS + VX_CFG_EXT_TCU_ENABLED + VX_CFG_EXT_DXA_ENABLED;
126	    local_mem_ = LocalMem::Create(sname, LocalMem::Config{
127	      (1 << VX_CFG_LMEM_LOG_SIZE),
128	      LSU_WORD_SIZE,
129	      lmem_num_reqs,
130	      log2ceil(VX_CFG_LMEM_NUM_BANKS),
131	      false
132	    });
133	
134	    // create lmem switch
135	    for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
136	      snprintf(sname, 100, "%s-lmem_switch%d", name.c_str(), b);
137	      lmem_switch_.at(b) = LocalMemSwitch::Create(sname, 1);
138	    }
139	
140	    // create per-block lmem adapters
141	    std::vector<LsuMemAdapter::Ptr> lsu_lmem_adapter(VX_CFG_NUM_LSU_BLOCKS);
142	    for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
143	      snprintf(sname, 100, "%s-lsu_lmem_adapter%d", name.c_str(), b);
144	      lsu_lmem_adapter.at(b) = LsuMemAdapter::Create(sname, LSU_CHANNELS, 1);
145	    }
146	
147	    // connect lmem switch to per-block adapters
148	    for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
149	      lmem_switch_.at(b)->ReqOutLmem.bind(&lsu_lmem_adapter.at(b)->ReqIn);
150	      lsu_lmem_adapter.at(b)->RspOut.bind(&lmem_switch_.at(b)->RspInLmem);
151	    }
152	
153	    // connect per-block lmem adapters to local memory ports
154	    for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
155	      for (uint32_t c = 0; c < LSU_CHANNELS; ++c) {
156	        lsu_lmem_adapter.at(b)->ReqOut.at(c).bind(&local_mem_->Inputs.at(b * LSU_CHANNELS + c));
157	        local_mem_->Outputs.at(b * LSU_CHANNELS + c).bind(&lsu_lmem_adapter.at(b)->RspIn.at(c));
158	      }
159	    }
160	
161	    // Per-channel request/response endpoints facing the dcache ports.
162	    std::vector<SimChannel<MemReq>*> dc_req_out(VX_CFG_NUM_LSU_BLOCKS * DCACHE_CHANNELS);
163	    std::vector<SimChannel<MemRsp>*> dc_rsp_in(VX_CFG_NUM_LSU_BLOCKS * DCACHE_CHANNELS);
164	
165	    if ((VX_CFG_NUM_LSU_LANES > 1) && (DCACHE_WORD_SIZE > LSU_WORD_SIZE)) {
166	      // connect memory coalescer; its memory side drives the dcache
167	      // channels directly (combinational lane fan-out/fan-in).
168	      for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
169	        lmem_switch_.at(b)->ReqOutDC.bind(&mem_coalescers_.at(b)->ReqIn);
170	        mem_coalescers_.at(b)->RspOut.bind(&lmem_switch_.at(b)->RspInDC);
171	        for (uint32_t c = 0; c < DCACHE_CHANNELS; ++c) {
172	          dc_req_out.at(b * DCACHE_CHANNELS + c) = &mem_coalescers_.at(b)->ReqOut.at(c);
173	          dc_rsp_in.at(b * DCACHE_CHANNELS + c) = &mem_coalescers_.at(b)->RspIn.at(c);
174	        }
175	      }
176	    } else {
177	      // bypass memory coalescer: per-block lane adapter (channel-fused
178	      // pass-through when DCACHE_CHANNELS == 1)
179	      std::vector<LsuMemAdapter::Ptr> lsu_dcache_adapter(VX_CFG_NUM_LSU_BLOCKS);
180	      for (uint32_t b = 0; b < VX_CFG_NUM_LSU_BLOCKS; ++b) {
181	        snprintf(sname, 100, "%s-lsu_dcache_adapter%d", name.c_str(), b);
182	        lsu_dcache_adapter.at(b) = LsuMemAdapter::Create(sname, DCACHE_CHANNELS, 1);
183	        lmem_switch_.at(b)->ReqOutDC.bind(&lsu_dcache_adapter.at(b)->ReqIn);
184	        lsu_dcache_adapter.at(b)->RspOut.bind(&lmem_switch_.at(b)->RspInDC);
185	        for (uint32_t c = 0; c < DCACHE_CHANNELS; ++c) {
186	          dc_req_out.at(b * DCACHE_CHANNELS + c) = &lsu_dcache_adapter.at(b)->ReqOut.at(c);
187	          dc_rsp_in.at(b * DCACHE_CHANNELS + c) = &lsu_dcache_adapter.at(b)->RspIn.at(c);
188	        }
189	      }
190	    }
191	
192	  #ifdef VX_CFG_VM_ENABLE
193	    // Per-core dcache MMU: TLB lookup + bypass for non-translated regions;
194	    // on miss, the embedded PTW FSM emits PTE fetches via ReqOut[0]
195	    // through the same cache hierarchy as regular loads.
196	    snprintf(sname, 100, "%s-dcache_mmu", name.c_str());
197	    dcache_mmu_ = Mmu::Create(sname, VX_CFG_DCACHE_NUM_REQS);
198	
199	    // Per-core icache MMU (1 port). Fetch reads/writes its upstream
200	    // channels (ReqIn[0]/RspOut[0]) directly; the downstream side is
201	    // bound to the Core's icache port below.
202	    snprintf(sname, 100, "%s-icache_mmu", name.c_str());
203	    icache_mmu_ = Mmu::Create(sname, 1);
204	
205	    // LSU memory side -> dcache MMU -> core's dcache port
206	    for (uint32_t p = 0; p < VX_CFG_NUM_LSU_BLOCKS * DCACHE_CHANNELS; ++p) {
207	      dc_req_out.at(p)->bind(&dcache_mmu_->ReqIn.at(p));
208	      dcache_mmu_->RspOut.at(p).bind(dc_rsp_in.at(p));
209	      dcache_mmu_->ReqOut.at(p).bind(&simobject_->dcache_req_out.at(p));
210	      simobject_->dcache_rsp_in.at(p).bind(&dcache_mmu_->RspIn.at(p));
211	    }
212	
213	    // icache MMU downstream side -> core's icache port. Upstream side
214	    // (ReqIn[0]/RspOut[0]) is consumed directly by fetch() in on_tick.
215	    icache_mmu_->ReqOut.at(0).bind(&simobject_->icache_req_out.at(0));
216	    simobject_->icache_rsp_in.at(0).bind(&icache_mmu_->RspIn.at(0));
217	  #else
218	    // No-VM: direct passthrough.
219	    for (uint32_t p = 0; p < VX_CFG_NUM_LSU_BLOCKS * DCACHE_CHANNELS; ++p) {
220	      dc_req_out.at(p)->bind(&simobject_->dcache_req_out.at(p));
221	      simobject_->dcache_rsp_in.at(p).bind(dc_rsp_in.at(p));
222	    }
223	  #endif
224	
225	    // initialize dispatchers
226	    dispatchers_.at((int)FUType::ALU) = SimPlatform::instance().create_object<Dispatcher>(name.c_str(), simobject_, VX_CFG_DISPATCH_QUEUE_SIZE, VX_CFG_NUM_ALU_BLOCKS, VX_CFG_NUM_ALU_LANES);
227	    dispatchers_.at((int)FUType::FPU) = SimPlatform::instance().create_object<Dispatcher>(name.c_str(), simobject_, VX_CFG_DISPATCH_QUEUE_SIZE, VX_CFG_NUM_FPU_BLOCKS, VX_CFG_NUM_FPU_LANES);
228	    dispatchers_.at((int)FUType::LSU) = SimPlatform::instance().create_object<Dispatcher>(name.c_str(), simobject_, VX_CFG_DISPATCH_QUEUE_SIZE, VX_CFG_NUM_LSU_BLOCKS, VX_CFG_NUM_LSU_LANES);
229	    dispatchers_.at((int)FUType::SFU) = SimPlatform::instance().create_object<Dispatcher>(name.c_str(), simobject_, VX_CFG_DISPATCH_QUEUE_SIZE, VX_CFG_NUM_SFU_BLOCKS, VX_CFG_NUM_SFU_LANES);
230	  #ifdef VX_CFG_EXT_TCU_ENABLE
231	    dispatchers_.at((int)FUType::TCU) = SimPlatform::instance().create_object<Dispatcher>(name.c_str(), simobject_, VX_CFG_DISPATCH_QUEUE_SIZE, VX_CFG_NUM_TCU_BLOCKS, VX_CFG_NUM_TCU_LANES);
232	  #endif
233	
234	    // initialize execute units
235	    snprintf(sname, 100, "%s-alu", name.c_str());
236	    func_units_.at((int)FUType::ALU) = SimPlatform::instance().create_object<AluUnit>(sname, simobject_);
237	    snprintf(sname, 100, "%s-fpu", name.c_str());
238	    func_units_.at((int)FUType::FPU) = SimPlatform::instance().create_object<FpuUnit>(sname, simobject_);
239	    snprintf(sname, 100, "%s-lsu", name.c_str());
240	    func_units_.at((int)FUType::LSU) = SimPlatform::instance().create_object<LsuUnit>(sname, simobject_);
241	    snprintf(sname, 100, "%s-sfu", name.c_str());
242	    func_units_.at((int)FUType::SFU) = SimPlatform::instance().create_object<SfuUnit>(sname, simobject_);
243	  #ifdef VX_CFG_EXT_TCU_ENABLE
244	    snprintf(sname, 100, "%s-tcu", name.c_str());
245	    tcu_unit_ = SimPlatform::instance().create_object<TcuUnit>(sname, simobject_);
246	    func_units_.at((int)FUType::TCU) = tcu_unit_;
247	
248	    // Bind the TCU tile-buffer subsystem (TcuTbuf) to its dedicated LMEM
249	    // port pair, appended after the LSU ports.
250	    {
251	      auto& tbuf = tcu_unit_->tbuf();
252	      uint32_t port = LSU_NUM_REQS;
253	      tbuf->lmem_req_out.bind(&local_mem_->Inputs.at(port));
254	      local_mem_->Outputs.at(port).bind(&tbuf->lmem_rsp_in);
255	    }
256	  #ifdef TCU_META_ENABLE
257	    // Bind the TCU metadata AGU to the LSU block-0 client port.
258	    {
259	      auto lsu = std::static_pointer_cast<LsuUnit>(func_units_.at((int)FUType::LSU));
260	      tcu_unit_->agu_req_out.bind(&lsu->TcuReqIn);
261	      lsu->TcuRspOut.bind(&tcu_unit_->agu_rsp_in);
262	    }
263	  #endif
264	  #endif
265	
266	    // commit arbiters — per-iw inputs are filled at runtime in commit() by
267	    // routing per-block FU outputs to commit_arbs_[trace->wid % VX_CFG_ISSUE_WIDTH]
268	    // (no static binding because the iw is not knowable at setup time when
269	    // NUM_*_BLOCKS < VX_CFG_ISSUE_WIDTH).
270	    for (uint32_t iw = 0; iw < VX_CFG_ISSUE_WIDTH; ++iw) {
271	      snprintf(sname, 100, "%s-commit-arb%d", name.c_str(), iw);
272	      commit_arbs_.at(iw) = TraceArbiter::Create(sname, ArbiterType::RoundRobin, (uint32_t)FUType::Count, 1);
273	    }
274	
275	    this->reset();
276	  }
277	
278	  void reset() {
279	    for (auto& arb : ibuffer_arbs_) {
280	      arb.reset();
281	    }
282	    for (auto& fc : fu_credits_) {
283	      std::fill(fc.begin(), fc.end(), 0);
284	    }
285	
286	    pending_instrs_.clear();
287	    pending_ifetches_ = 0;
288	
289	    std::fill(ibuf_inflight_.begin(), ibuf_inflight_.end(), 0);
290	
291	    perf_stats_ = PerfStats();
292	  }
293	
294	  void tick() {
295	    this->commit();
296	    this->execute();
297	    this->issue();
298	    this->decode();
299	    this->fetch();
300	    this->schedule();
301	
302	    ++perf_stats_.cycles;
303	    DPN(2, std::flush);
304	  }
305	
306	  // ----- Pipeline stages (private) -----
307	
308	  void schedule() {
309	    // profiling
310	    perf_stats_.active_warps += scheduler_->active_warps().count();
311	    perf_stats_.stalled_warps += scheduler_->stalled_warps().count();
312	
313	    // stop when fetch_latch cannot accept
314	    if (fetch_latch_.full())
315	      return;
316	
317	    // eligible warps: ibuffer not yet saturated
318	    WarpMask warp_mask;
319	    for (uint32_t w = 0, nw = VX_CFG_NUM_WARPS; w < nw; ++w) {
320	      if (ibuf_inflight_.at(w) < VX_CFG_IBUF_SIZE) {
321	        warp_mask.set(w);
322	      }
323	    }
324	
325	    auto trace = scheduler_->schedule(warp_mask);
326	    if (trace == nullptr) {
327	      ++perf_stats_.sched_idle;
328	      return;
329	    }
330	
331	    fetch_latch_.push(trace);
332	    DT(3, simobject_->name() << "-pipeline schedule: " << *trace);
333	    pending_instrs_.push_back(trace);
334	    ++ibuf_inflight_.at(trace->wid);
335	    perf_stats_.issued_warps += 1;
336	    perf_stats_.issued_threads += trace->tmask.count();
337	  }
338	
339	  void fetch() {
340	    perf_stats_.ifetch_latency += pending_ifetches_;
341	
342	  #ifdef VX_CFG_VM_ENABLE
343	    // With VM, fetch reads/writes the icache MMU's upstream channels.
344	    // The MMU translates and forwards to simobject_->icache_req_out
345	    // downstream (driven by SimChannel binding in the constructor).
346	    auto& icache_rsp = icache_mmu_->RspOut.at(0);
347	    auto& icache_req = icache_mmu_->ReqIn.at(0);
348	  #else
349	    auto& icache_rsp = simobject_->icache_rsp_in.at(0);
350	    auto& icache_req = simobject_->icache_req_out.at(0);
351	  #endif
352	
353	    // handle icache response — extract instruction word from the TLM line payload
354	    if (!icache_rsp.empty()){
355	      auto& mem_rsp = icache_rsp.peek();
356	      auto trace = pending_icache_.at(mem_rsp.tag);
357	      assert(mem_rsp.data && "icache response must carry line payload");
358	
359	    #ifdef VX_CFG_EXT_C_ENABLE
360	      // Decompressor classifies the rsp: emit-ready (sets trace->code) or
361	      // queues a refetch internally for cross-word 32-bit completion.
362	      bool emit = decompressor_->on_icache_rsp(trace, *mem_rsp.data);
363	      bool progressed = !emit || decode_latch_.try_push(trace);
364	    #else
365	      bool emit = true;
366	      bool progressed = false;
367	      if (decode_latch_.try_push(trace)) {
368	        uint32_t offset = trace->PC & (VX_CFG_MEM_BLOCK_SIZE - 1);
369	        std::memcpy(&trace->code, mem_rsp.data->data() + offset, sizeof(uint32_t));
370	        progressed = true;
371	      }
372	    #endif
373	      if (progressed) {
374	        if (emit) {
375	          DP(1, "Fetch: code=0x" << std::hex << trace->code << std::dec << ", cid=" << trace->cid
376	                 << ", wid=" << trace->wid << ", tmask=" << trace->tmask
377	                 << ", PC=0x" << std::hex << trace->PC << " (#" << std::dec << trace->uuid << ")");
378	        }
379	        DT(3, simobject_->name() << " icache-rsp: addr=0x" << std::hex << trace->PC << ", tag=0x" << mem_rsp.tag << std::dec << ", " << *trace);
380	        pending_icache_.release(mem_rsp.tag);
381	        icache_rsp.pop();
382	        --pending_ifetches_;
383	      }
384	    }
385	
386	    // send icache request — under EXT_C the FSM drains pending refetches
387	    // (cross-word completions) before fresh schedule traces.
388	    instr_trace_t* trace = nullptr;
389	    Word           req_addr = 0;
390	  #ifdef VX_CFG_EXT_C_ENABLE
391	    bool           from_refetch = false;
392	    {
393	      auto pick = decompressor_->pick_request(fetch_latch_.empty() ? nullptr
394	                                                              : fetch_latch_.peek());
395	      trace        = pick.trace;
396	      req_addr     = pick.addr;
397	      from_refetch = pick.from_refetch;
398	    }
399	  #else
400	    if (!fetch_latch_.empty()) {
401	      trace    = fetch_latch_.peek();
402	      req_addr = trace->PC;
403	    }
404	  #endif
405	    if (trace == nullptr)
406	      return;
407	
408	    // Avoid leaking icache tags when the request port back-pressures.
409	    if (pending_icache_.full()) {
410	      ++perf_stats_.fetch_stalls;
411	      return;
412	    }
413	
414	    MemReq mem_req;
415	    // Address goes downstream as VA. The icache MMU (under VX_CFG_VM_ENABLE)
416	    // substitutes PA before forwarding; with VM off, this is just the PA.
417	    mem_req.addr  = req_addr;
418	    // op defaults to MemOp::LD — icache request is a load.
419	    uint32_t tag = pending_icache_.allocate(trace);
420	    mem_req.tag   = tag;
421	    mem_req.hart_id   = trace->cid;
422	    mem_req.uuid  = trace->uuid;
423	    if (icache_req.try_send(mem_req)) {
424	      DT(3, simobject_->name() << " icache-req: addr=0x" << std::hex << mem_req.addr << ", tag=0x" << mem_req.tag << std::dec << ", " << *trace);
425	    #ifdef VX_CFG_EXT_C_ENABLE
426	      decompressor_->commit_request(from_refetch);
427	      if (!from_refetch) fetch_latch_.pop();
428	    #else
429	      fetch_latch_.pop();
430	    #endif
431	      ++perf_stats_.ifetches;
432	      ++pending_ifetches_;
433	    } else {
434	      pending_icache_.release(tag);
435	      ++perf_stats_.fetch_stalls;
436	    }
437	  }
438	
439	  void decode() {
440	    if (decode_latch_.empty())
441	      return;
442	
443	    auto trace = decode_latch_.peek();
444	
445	    // check ibuffer capacity
446	    auto& ibuffer = ibuffers_.at(trace->wid);
447	    if (ibuffer->full()) {
448	      if (!trace->log_once(true)) {
449	        DT(4, simobject_->name() << " ibuffer-stall: " << *trace);
450	      }
451	      ++perf_stats_.ibuf_stalls;
452	      return;
453	    } else {
454	      trace->log_once(false);
455	    }
456	
457	    // Decode: fill trace metadata from instruction bits. The decoder
458	    // recognises RVC encoding (low 2 bits != 11), expands internally, and
459	    // stamps IntrBrArgs.is_rvc.
460	    auto instr = decoder_->decode(trace->code, trace->uuid);
461	    DP(1, "Instr: " << *instr << " (#" << trace->uuid << ")");
462	    trace->instr_ptr   = instr;
463	    trace->fu_type     = instr->get_fu_type();
464	    trace->op_type     = instr->get_op_type();
465	    trace->dst_reg     = instr->get_dest_reg();
466	    trace->dst_bytesel = instr->get_dst_bytesel();
467	    for (uint32_t i = 0; i < NUM_SRC_REGS; ++i) {
468	      trace->src_regs[i] = instr->get_src_reg(i);
469	    }
470	    // Filter x0 for integer dest: writes to x0 are silent in RISC-V, so don't
471	    // reserve a scoreboard slot — the unit's writeback skips x0 too.
472	    auto dst = instr->get_dest_reg();
473	    trace->wb = (dst.type != RegType::None)
474	             && !(dst.type == RegType::Integer && dst.idx == 0);
475	    trace->fetch_stall = instr->is_wstall();
476	    // A warp blocked on a stalling instruction is released when that
477	    // instruction commits. Default to releasing every stalling instruction;
478	    // warp-control (SFU) refines this for ops whose warp is instead released by
479	    // the barrier/spawn machinery (see SfuUnit::on_tick).
480	    trace->resume_warp = trace->fetch_stall;
481	
482	    // Advance the warp's PC by the instruction's true size (2 bytes for RVC,
483	    // 4 bytes otherwise). Branch/JAL/JALR commit later overrides warp.PC
484	    // with the resolved target.
485	    {
486	      bool is_rvc = (trace->code & 0x3u) != 0x3u;
487	      scheduler_->advance_pc(trace, is_rvc ? 2 : 4);
488	    }
489	
490	    // Resume warp for non-stalling instructions (ALU, FPU);
491	    // stalling instructions (LSU, SFU, TCU, branches) stay suspended until commit
492	    if (!trace->fetch_stall) {
493	      scheduler_->resume(trace->wid);
494	    }
495	
496	    DT(3, simobject_->name() << "-pipeline decode: " << *trace);
497	
498	    // insert to ibuffer
499	    ibuffer->push(trace);
500	
501	    decode_latch_.pop();
502	  }
503	
504	  void issue() {
505	    // dispatch operands
506	    for (uint32_t iw = 0; iw < VX_CFG_ISSUE_WIDTH; ++iw) {
507	      auto& operand = operands_.at(iw);
508	      if (operand->Output.empty())
509	        continue;
510	      auto trace = operand->Output.peek();
511	      if (dispatchers_.at((int)trace->fu_type)->Inputs.at(iw).try_send(trace)) {
512	        operand->Output.pop();
513	      }
514	    }
515	
516	    // issue ibuffer instructions
517	    for (uint32_t iw = 0; iw < VX_CFG_ISSUE_WIDTH; ++iw) {
518	      bool any_scrb_blocked = false;
519	      BitVector<> ready_set(PER_ISSUE_WARPS);
520	      BitVector<> suppress_set(PER_ISSUE_WARPS);
521	      for (uint32_t w = 0; w < PER_ISSUE_WARPS; ++w) {
522	        uint32_t wid = w * VX_CFG_ISSUE_WIDTH + iw;
523	        auto& ibuffer = ibuffers_.at(wid);
524	        if (ibuffer->empty())
525	          continue;
526	
527	        // check scoreboard against sequencer micro-op (handles uop WAW/RAW)
528	        auto trace = ibuffer->peek();
529	        auto seq = sequencers_.at(wid);
530	        auto uop_trace = seq->get(trace);  // returns cached uop or generates next
531	
532	        if (scoreboard_->in_use(uop_trace)) {
533	          auto uses = scoreboard_->get_uses(uop_trace);
534	          if (!uop_trace->log_once(true)) {
535	            DTH(4, "*** scoreboard-stall: dependents={");
536	            for (uint32_t j = 0, n = uses.size(); j < n; ++j) {
537	              auto& use = uses.at(j);
538	              __unused (use);
539	              if (j) DTN(4, ", ");
540	              DTN(4, use.reg_type << use.reg_id << " (#" << use.uuid << ")");
541	            }
542	            DTN(4, "}, " << *uop_trace << std::endl);
543	          }
544	          // Count once per cycle per issue slice regardless of how many
545	          // warps are blocked.
546	          any_scrb_blocked = true;
547	        } else {
548	          uop_trace->log_once(false);
549	          // FU lock: block warps whose target FU is locked by another warp.
550	          // fu_lock=1 means acquire request; blocked when FU already locked.
551	          auto fu = (int)uop_trace->fu_type;
552	          bool uop_fu_lock = uop_trace->instr_ptr->get_fu_lock();
553	          if (fu_locked_.at(iw).test(fu) && uop_fu_lock) {
554	            continue; // blocked by FU lock
555	          }
556	        #ifdef VX_CFG_EXT_RTU_ENABLE
557	          // A TRACE2 macro must hold a ray-pool slot before its head uop enters
558	          // the SFU, or it stalls at the head of that unit's queue and starves
559	          // the WAIT2 that would release one. Claiming it here, rather than
560	          // testing for a free one, also keeps another core from taking the
561	          // last slot between issue and execute.
562	          if (!this->rtu_trace2_reserve(uop_trace)) {
563	            continue; // ray pool full
564	          }
565	        #endif
566	          ready_set.set(w); // mark instruction as ready
567	          // suppress warps whose target FU dispatch queue is going-full. Credit
568	          // based: spent at issue, returned at FU accept, so it counts in-flight
569	          // ops still in operand collection (like the RTL scoreboard), not just
570	          // what has already reached the queue.
571	          if (fu_credits_.at(iw).at(fu) >= VX_CFG_DISPATCH_QUEUE_SIZE - 1) {
572	            suppress_set.set(w);
573	          }
574	        }
575	      }
576	
577	      if (ready_set.any()) {
578	        // Only suppress when at least one warp can issue to a free FU;
579	        // otherwise let all warps through so the pipeline absorbs transient stalls.
580	        BitVector<> eff_suppress(PER_ISSUE_WARPS);
581	        auto unsuppressed = ready_set & ~suppress_set;
582	        if (unsuppressed.any()) {
583	          eff_suppress = suppress_set;
584	        }
585	        // select one instruction from ready set
586	        auto w = ibuffer_arbs_.at(iw).grant(ready_set, eff_suppress);
587	        uint32_t wid = w * VX_CFG_ISSUE_WIDTH + iw;
588	        auto& ibuffer = ibuffers_.at(wid);
589	        auto trace = ibuffer->peek();
590	
591	        // Retrieve the (already-generated) micro-op from the sequencer
592	        auto seq = sequencers_.at(wid);
593	        auto uop_trace = seq->get(trace);
594	
595	        // to operand stage
596	        if (operands_.at(iw)->Input.try_send(uop_trace)) {
597	          // capture register operands at issue (Operands owns regfile)
598	          operands_.at(iw)->fetch_operands(uop_trace);
599	          // spend a dispatch credit for the target FU
600	          ++fu_credits_.at(iw).at((int)uop_trace->fu_type);
601	          DT(3, simobject_->name() << "-pipeline issue: " << *uop_trace);
602	          if (uop_trace->wb) {
603	            // update scoreboard
604	            scoreboard_->reserve(uop_trace);
605	          }
606	          // Update FU lock state: 10=acquire, 01=release
607	          {
608	            auto fui = (int)uop_trace->fu_type;
609	            bool fl = uop_trace->instr_ptr->get_fu_lock();
610	            bool ful = uop_trace->instr_ptr->get_fu_unlock();
611	            if (fl && !ful) {
612	              fu_locked_.at(iw).set(fui);
613	            } else if (!fl && ful) {
614	              fu_locked_.at(iw).reset(fui);
615	            }
616	          }
617	          // Advance sequencer; pop ibuffer only when all micro-ops issued
618	          if (seq->advance()) {
619	            // Resume warp for macro instructions that stalled fetch at decode
620	            if (trace->instr_ptr->is_macro_op()) {
621	              scheduler_->resume(trace->wid);
622	              // Macro trace never reaches commit (only micro-ops do),
623	              // so remove it from pending tracking and deallocate here.
624	              pending_instrs_.remove(trace);
625	              trace->~instr_trace_t();
626	              trace_pool_.deallocate(trace, 1);
627	            }
628	            ibuffer->pop();
629	            // Release ibuffer backpressure slot (matches ++ in schedule()).
630	            // Saturating decrement: flush_warp_pipeline only drains the
631	            // ibuffer + resets ibuf_inflight to 0, but fetch_latch_ /
632	            // decode-stage entries scheduled pre-trap can still arrive
633	            // at issue() post-flush and decrement the (now-zeroed)
634	            // counter. Async-trap users (RTU CB_YIELD path: AHS, CHS,
635	            // MISS) routinely hit this; a non-saturating decrement
636	            // underflows to UINT32_MAX and stalls scheduling. Proper
637	            // fix is to extend flush_warp_pipeline to also drain
638	            // fetch_latch_ + pending icache fetches for the warp.
639	            if (ibuf_inflight_.at(wid) > 0) {
640	              --ibuf_inflight_.at(wid);
641	            }
642	          }
643	        }
644	      }
645	
646	      // track scoreboard stalls
647	      if (any_scrb_blocked) {
648	        ++perf_stats_.scrb_stalls;
649	      }
650	    }
651	  }
652	
653	  void execute() {
654	    // Dispatcher.Outputs are sized per FU's NUM_*_BLOCKS; FU.Inputs match.
655	    // Per-block 1:1 forward (the dispatcher already handled IW→NB aggregation).
656	    for (uint32_t fu = 0; fu < (uint32_t)FUType::Count; ++fu) {
657	      auto& dispatch = dispatchers_.at(fu);
658	      auto& func_unit = func_units_.at(fu);
659	      uint32_t nb = func_unit->num_blocks();
660	      for (uint32_t b = 0; b < nb; ++b) {
661	        if (dispatch->Outputs.at(b).empty())
662	          continue;
663	        auto trace = dispatch->Outputs.at(b).peek();
664	        if (func_unit->input(b).try_send(trace)) {
665	          dispatch->Outputs.at(b).pop();
666	          // return the dispatch credit on FU accept
667	          uint32_t iw = trace->wid % VX_CFG_ISSUE_WIDTH;
668	          if (fu_credits_.at(iw).at(fu) > 0)
669	            --fu_credits_.at(iw).at(fu);
670	        } else {
671	          // track functional unit stalls
672	          switch ((FUType)fu) {
673	          case FUType::ALU: ++perf_stats_.alu_stalls; break;
674	          case FUType::FPU: ++perf_stats_.fpu_stalls; break;
675	          case FUType::LSU: ++perf_stats_.lsu_stalls; break;
676	          case FUType::SFU: ++perf_stats_.sfu_stalls; break;
677	        #ifdef VX_CFG_EXT_TCU_ENABLE
678	          case FUType::TCU: ++perf_stats_.tcu_stalls; break;
679	        #endif
680	          default: assert(false);
681	          }
682	        }
683	      }
684	    }
685	  }
686	
687	  void commit() {
688	    // Fan-in: route per-block FU outputs to per-iw commit arbs by trace->wid.
689	    // Each FU has NUM_*_BLOCKS outputs; the original iw was lost during
690	    // dispatcher aggregation, so we recover it from the warp id and try_send
691	    // into the matching commit_arb input slot.
692	    for (uint32_t fu = 0; fu < (uint32_t)FUType::Count; ++fu) {
693	      auto& func_unit = func_units_.at(fu);
694	      uint32_t nb = func_unit->num_blocks();
695	      for (uint32_t b = 0; b < nb; ++b) {
696	        auto& fu_out = func_unit->output(b);
697	        if (fu_out.empty())
698	          continue;
699	        auto trace = fu_out.peek();
700	        uint32_t iw = trace->wid % VX_CFG_ISSUE_WIDTH;
701	        auto& arb_in = commit_arbs_.at(iw)->Inputs.at(fu);
702	        if (arb_in.try_send(trace)) {
703	          // Release the warp as soon as its stalling instruction's result leaves
704	          // the functional unit — the branch target / fence / warp-control is
705	          // resolved at that point. The release lands in stalled_warps so the
706	          // scheduler observes it next cycle.
707	          if (trace->eop && trace->resume_warp) {
708	            scheduler_->resume(trace->wid);
709	          }
710	          fu_out.pop();
711	        }
712	      }
713	    }
714	
715	    // process completed instructions
716	    for (uint32_t iw = 0; iw < VX_CFG_ISSUE_WIDTH; ++iw) {
717	      auto& commit_arb = commit_arbs_.at(iw);
718	      if (commit_arb->Outputs.at(0).empty())
719	        continue;
720	      auto trace = commit_arb->Outputs.at(0).peek().data;
721	
722	      // advance to commit stage
723	      DT(3, simobject_->name() << "-pipeline commit: " << *trace);
724	      assert(trace->cid == simobject_->id());
725	
726	      // Per-pid writeback: dispatcher splits multi-pid traces into copies
727	      // each carrying its own lane-subset tmask + dst_data; every pid pass
728	      // writes back independently. Scoreboard release counts COMMITS via
729	      // num_pkts (set by dispatcher at sop) rather than gating on eop —
730	      // cache responses can complete out of order, so a SIMD-split eop
731	      // packet may reach commit before its peers; releasing on eop would
732	      // expose stale lanes to the next dependent instruction's
733	      // fetch_operands. Perf accounting still gates on eop.
734	      if (trace->wb) {
735	        operands_.at(iw)->writeback(trace);
736	        if (scoreboard_->commit_packet(trace)) {
737	          scoreboard_->release(trace);
738	        }
739	      }
740	
741	      if (trace->eop) {
742	
743	        // instruction mix profiling
744	        switch (trace->fu_type) {
745	        case FUType::ALU: ++perf_stats_.alu_instrs; break;
746	        case FUType::FPU: ++perf_stats_.fpu_instrs; break;
747	        case FUType::LSU: ++perf_stats_.lsu_instrs; break;
748	        case FUType::SFU: ++perf_stats_.sfu_instrs; break;
749	      #ifdef VX_CFG_EXT_TCU_ENABLE
750	        case FUType::TCU: ++perf_stats_.tcu_instrs; break;
751	      #endif
752	        default: assert(false);
753	        }
754	        // track committed instructions
755	        perf_stats_.instrs += 1;
756	
757	        // instruction completed
758	        pending_instrs_.remove(trace);
759	      }
760	
761	      trace->~instr_trace_t();
762	      trace_pool_.deallocate(trace, 1);
763	
764	      commit_arb->Outputs.at(0).pop();
765	    }
766	  }
