785	
786	  // Drop every unissued instruction for the given warp and return the PC
787	  // at which execution should resume. Used by Scheduler::raise_async_trap
788	  // to emulate a real RISC-V trap-entry pipeline flush — without it, the
789	  // pre-trap instructions in the ibuffer prevent the post-trap fetch from
790	  // making progress (ibuf_inflight pegged at IBUF_SIZE).
791	  Word flush_warp_pipeline(uint32_t wid) {
792	    auto& ibuffer = ibuffers_.at(wid);
793	    Word first_pc = 0;
794	    bool have_first = false;
795	    while (!ibuffer->empty()) {
796	      auto trace = ibuffer->peek();
797	      if (!have_first) {
798	        first_pc = trace->PC;
799	        have_first = true;
800	      }
801	      pending_instrs_.remove(trace);
802	      trace->~instr_trace_t();
803	      trace_pool_.deallocate(trace, 1);
804	      ibuffer->pop();
805	    }
806	    ibuf_inflight_.at(wid) = 0;
807	    // The sequencer may cache the just-flushed trace in state_.current_uop
808	    // (set by seq->get() during a prior issue tick where the trace stalled
809	    // on scoreboard or FU lock). That cached pointer is now dangling —
810	    // drop it so the post-trap issue cycle re-derives state from the
811	    // post-mret ibuffer.
812	    sequencers_.at(wid)->flush();
813	    // If the ibuffer was empty (rare: trap fires before any post-TRACE
814	    // instruction made it into ibuffer), the caller's warp.PC is the
815	    // correct resume point. Caller handles that case.
816	    return have_first ? first_pc : Word(0);
817	  }
