823	  int dcr_read(uint32_t addr, uint32_t tag, uint32_t* value) {
824	    // tag arrives as (mpm_class << 6) | mpm_tag_idx after socket strips core_id
825	    switch (addr) {
826	    case VX_DCR_BASE_CACHE_FLUSH:
827	      *value = 0;
828	      break;
829	    case VX_DCR_BASE_MPM_VALUE: {
830	      uint32_t mpm_class   = tag >> 6;
831	      uint32_t mpm_tag_idx = tag & 0x3f;
832	      bool     is_hi       = (mpm_tag_idx >> 5) & 1;
833	      uint32_t idx         = mpm_tag_idx & 0x1f;
834	      uint32_t csr_addr    = is_hi ? (VX_CSR_MPM_BASE_H + idx) : (VX_CSR_MPM_BASE + idx);
835	      auto saved_class = mpm_class_;
836	      mpm_class_ = mpm_class;
837	      *value = static_cast<uint32_t>(this->csr_unit().get_csr(csr_addr, 0, 0));
838	      mpm_class_ = saved_class;
839	      break;
840	    }
841	    default:
842	      break;
843	    }
844	    return 0;
845	  }
