888	  // Only a TRACE2 macro head claims a ray-pool slot; every other uop holds no
889	  // new resource. The claim is per-warp and idempotent, so a warp that passes
890	  // the ready-scan but loses arbitration keeps its slot for the next cycle.
891	  bool rtu_trace2_reserve(const instr_trace_t* uop_trace) {
892	    auto rtu_p = std::get_if<RtuType>(&uop_trace->op_type);
893	    if (rtu_p == nullptr || *rtu_p != RtuType::TRACE2) {
894	      return true;
895	    }
896	    auto args = std::get<IntrRtuArgs>(uop_trace->instr_ptr->get_args());
897	    if (args.uop != 0) {
898	      return true;
899	    }
900	    return this->sfu_unit()->rtu_trace2_reserve_slot(uop_trace->wid);
901	  }
