46	using namespace vortex;
47	
48	class Cluster::Impl {
49	public:
50	  Impl(Cluster* simobject)
51	    : simobject_(simobject)
52	    , sockets_(NUM_SOCKETS)
53	    , gbarriers_(VX_CFG_NUM_BARRIERS)
54	    , cores_per_socket_(VX_CFG_SOCKET_SIZE)
55	  {
56	    const std::string& name = simobject_->name();
57	    char sname[100];
58	
59	    uint32_t sockets_per_cluster = sockets_.size();
60	    uint32_t cluster_id = simobject_->id();
61	
62	    // create sockets
63	
64	    for (uint32_t i = 0; i < sockets_per_cluster; ++i) {
65	      uint32_t socket_id = cluster_id * sockets_per_cluster + i;
66	      snprintf(sname, 100, "%s-socket%d", name.c_str(), i);
67	      sockets_.at(i) = Socket::Create(sname, socket_id, simobject_);
68	    }
69	
70	    // Create l2cache
71	
72	    snprintf(sname, 100, "%s-l2cache", name.c_str());
73	    // L2 is the LLC iff L2 is enabled and L3 is not.
74	    l2cache_ = Cache::Create(sname, Cache::Config{
75	      !VX_CFG_L2_ENABLED,
76	      log2ceil(VX_CFG_L2_SIZE),// C
77	      log2ceil(VX_CFG_L2_LINE_SIZE),// L
78	      log2ceil(VX_CFG_L2_SECTOR_SIZE),// S
79	      log2ceil(VX_CFG_L1_LINE_SIZE), // W
80	      log2ceil(VX_CFG_L2_NUM_WAYS),  // A
81	      log2ceil(VX_CFG_L2_NUM_BANKS), // B
82	      VX_CFG_XLEN,                   // address bits
83	      VX_CFG_L2_NUM_REQS,            // request size
84	      VX_CFG_L2_MEM_PORTS,           // memory ports
85	      VX_CFG_L2_WRITEBACK,           // write-back
86	      false,                  // write response
87	      VX_CFG_L2_MSHR_SIZE,           // mshr size
88	      VX_CFG_L2_LATENCY,             // pipeline latency
89	      VX_CFG_L2_REPL_POLICY,         // replacement policy
90	      (VX_CFG_L2_ENABLED != 0) && (VX_CFG_L3_ENABLED == 0), // is_llc
91	    });
92	
93	
94	    // connect l2cache memory interface
95	    for (uint32_t i = 0; i < VX_CFG_L2_MEM_PORTS; ++i) {
96	      l2cache_->mem_req_out.at(i).bind(&simobject_->mem_req_out.at(i));
97	      simobject_->mem_rsp_in.at(i).bind(&l2cache_->mem_rsp_in.at(i));
98	    }
99	
100	    // ── L2 fan-in: sockets + optional extension caches ─────────────────
101	    // Row 0 = sockets (high priority).
102	    // Row 1 = DXA GMEM (if enabled).
103	    // Row 2 = tcache (if enabled).
104	    // Row 3 = ocache (if enabled).
105	    // Row 4 = rcache (if enabled).
106	    // Row 5 = RTU dcache (if enabled).
107	    // The priority arbiter lets sockets win over extension traffic on
108	    // contention, matching the RTL `VX_mem_arb` priority ordering.
109	#if defined(VX_CFG_EXT_DXA_ENABLE) || defined(VX_CFG_EXT_TEX_ENABLE) || defined(VX_CFG_EXT_OM_ENABLE) || defined(VX_CFG_EXT_RASTER_ENABLE) || defined(VX_CFG_EXT_RTU_ENABLE)
110	    constexpr uint32_t kL2Rows = 1
111	        + VX_CFG_EXT_DXA_ENABLED + VX_CFG_EXT_TEX_ENABLED + VX_CFG_EXT_OM_ENABLED + VX_CFG_EXT_RASTER_ENABLED + VX_CFG_EXT_RTU_ENABLED;
112	    snprintf(sname, 100, "%s-l2arb", name.c_str());
113	    auto l2arb = MemArbiter::Create(sname, ArbiterType::Priority,
114	                                    kL2Rows * VX_CFG_L2_NUM_REQS, VX_CFG_L2_NUM_REQS);
115	    // sockets → row 0
116	    for (uint32_t i = 0; i < sockets_per_cluster; ++i) {
117	      for (uint32_t j = 0; j < VX_CFG_L1_MEM_PORTS; ++j) {
118	        uint32_t port = i * VX_CFG_L1_MEM_PORTS + j;
119	        sockets_.at(i)->mem_req_out.at(j).bind(&l2arb->ReqIn.at(kL2Rows * port + 0));
120	        l2arb->RspOut.at(kL2Rows * port + 0).bind(&sockets_.at(i)->mem_rsp_in.at(j));
121	      }
122	    }
123	#else
124	    // No L2-sharing extensions: direct sockets → L2.
125	    for (uint32_t i = 0; i < sockets_per_cluster; ++i) {
126	      for (uint32_t j = 0; j < VX_CFG_L1_MEM_PORTS; ++j) {
127	        sockets_.at(i)->mem_req_out.at(j).bind(&l2cache_->core_req_in.at(i * VX_CFG_L1_MEM_PORTS + j));
128	        l2cache_->core_rsp_out.at(i * VX_CFG_L1_MEM_PORTS + j).bind(&sockets_.at(i)->mem_rsp_in.at(j));
129	      }
130	    }
131	#endif // any L2-sharing extension
132	
133	#ifdef VX_CFG_EXT_DXA_ENABLE
134	    // Create DxaCore at cluster scope
135	    snprintf(sname, 100, "%s-dxa-core", name.c_str());
136	    dxa_core_ = DxaCore::Create(sname, simobject_);
137	
138	    // DXA gmem → row 1 of l2arb.
139	    constexpr uint32_t kDxaRow = 1;
140	    uint32_t kDxaMemPorts = dxa_core_->gmem_req_out.size();
141	    for (uint32_t i = 0; i < kDxaMemPorts; ++i) {
142	      dxa_core_->gmem_req_out.at(i).bind(&l2arb->ReqIn.at(kL2Rows * i + kDxaRow));
143	      l2arb->RspOut.at(kL2Rows * i + kDxaRow).bind(&dxa_core_->gmem_rsp_in.at(i));
144	    }
145	
146	    // Per-core SFU.dxa_req_out (DxaUnit decodes onto it) → DxaCore::dxa_req_in[cid].
147	    for (uint32_t s = 0; s < sockets_per_cluster; ++s) {
148	      for (uint32_t c = 0; c < cores_per_socket_; ++c) {
149	        uint32_t cid = s * cores_per_socket_ + c;
150	        auto sfu = sockets_.at(s)->core(c)->sfu_unit();
151	        sfu->dxa_req_out.bind(&dxa_core_->dxa_req_in.at(cid));
152	      }
153	    }
154	
155	    // DxaCore::lmem_req_out[cid] → core's LocalMem.Inputs[port_dxa].
156	    // A tx_callback on the channel fires barrier_event_release for each
157	    // DXA-write packet carrying notify_done at the cycle LMEM receives it.
158	    uint32_t port_dxa = LSU_NUM_REQS;
159	  #ifdef VX_CFG_EXT_TCU_ENABLE
160	    port_dxa += 1;
161	  #endif
162	    for (uint32_t s = 0; s < sockets_per_cluster; ++s) {
163	      for (uint32_t c = 0; c < cores_per_socket_; ++c) {
164	        uint32_t cid = s * cores_per_socket_ + c;
165	        Core* core = sockets_.at(s)->core(c).get();
166	        auto& ch = dxa_core_->lmem_req_out.at(cid);
167	        ch.bind(&core->local_mem()->Inputs.at(port_dxa));
168	        ch.tx_callback([core](const MemReq& req, uint64_t /*cycles*/) {
169	          if (req.is_write() && req.flags.dxa_notify_done) {
170	            // notify_bar_id arrives in raw (encoded) form: low byte = cta_no,
171	            // bits[30:8] = bar_no. Decode to flat barrier index before release.
172	            uint32_t decoded = bar_decode_id(req.flags.dxa_notify_bar_id, VX_CFG_NUM_BARRIERS);
173	            core->barrier_event_release(decoded);
174	          }
175	        });
176	      }
177	    }
178	#endif
179	
180	#ifdef VX_CFG_EXT_TEX_ENABLE
181	    // ── Cluster-shared TEX engine + tcache ──────────────────────────────
182	    snprintf(sname, 100, "%s-tex-core", name.c_str());
183	    tex_core_ = TexCore::Create(sname, simobject_);
184	
185	    // tcache: read-only TLM Cache, config from VX_config.toml [tcache] section.
186	    snprintf(sname, 100, "%s-tcache", name.c_str());
187	    constexpr uint32_t kTcacheLineSize = VX_CFG_MEM_BLOCK_SIZE; // = TCACHE_LINE_SIZE = VX_CFG_L1_LINE_SIZE
188	    constexpr uint32_t kTcacheWordSize = 4;              // = TCACHE_WORD_SIZE
189	    constexpr uint32_t kTcacheNumReqs  = VX_CFG_TCACHE_NUM_BANKS;
190	    constexpr uint32_t kTcacheMemPorts = 1;              // = TCACHE_MEM_PORTS
191	    auto tcache = Cache::Create(sname, Cache::Config{
192	      false,                       // bypass
193	      log2ceil(VX_CFG_TCACHE_SIZE),       // C
194	      log2ceil(kTcacheLineSize),   // L
195	      log2ceil(kTcacheLineSize),   // S (no sectoring)
196	      log2ceil(kTcacheWordSize),   // W
197	      log2ceil(VX_CFG_TCACHE_NUM_WAYS),   // A
198	      log2ceil(VX_CFG_TCACHE_NUM_BANKS),  // B
199	      VX_CFG_XLEN,                        // address bits
200	      kTcacheNumReqs,              // request size
201	      kTcacheMemPorts,             // memory ports
202	      false,                       // write-back (read-only cache)
203	      false,                       // write response
204	      VX_CFG_TCACHE_MSHR_SIZE,            // mshr size
205	      2,                           // pipeline latency
206	      uint8_t(VX_CFG_L2_REPL_POLICY),     // replacement policy (use L2 policy as default)
207	      false,                       // is_llc (TCACHE is auxiliary, not LLC)
208	    });
209	    tcache_ = tcache;
210	
211	    // tex_core ↔ tcache (per-port).
212	    for (uint32_t i = 0; i < kTcacheNumReqs; ++i) {
213	      tex_core_->tcache_req_out.at(i).bind(&tcache->core_req_in.at(i));
214	      tcache->core_rsp_out.at(i).bind(&tex_core_->tcache_rsp_in.at(i));
215	    }
216	    // tcache memory side → l2arb. Row index = kL2Rows-1 if no OM, else
217	    // kL2Rows-2 (OM occupies the last row when both are present).
218	    constexpr uint32_t kTexRow = 1 + VX_CFG_EXT_DXA_ENABLED;
219	    for (uint32_t i = 0; i < kTcacheMemPorts; ++i) {
220	      tcache->mem_req_out.at(i).bind(&l2arb->ReqIn.at(kL2Rows * i + kTexRow));
221	      l2arb->RspOut.at(kL2Rows * i + kTexRow).bind(&tcache->mem_rsp_in.at(i));
222	    }
223	
224	    // Cluster-level TexBus arbiter: NUM_CORES_PER_CLUSTER inputs (one per
225	    // SfuUnit) → 1 TEX-core lane (kNumTexCores=1 by default).
226	    snprintf(sname, 100, "%s-tex-bus", name.c_str());
227	    uint32_t cores_per_cluster = sockets_per_cluster * cores_per_socket_;
228	    auto tex_bus = TexBusArbiter::Create(sname, ArbiterType::RoundRobin,
229	                                         cores_per_cluster, 1);
230	    tex_bus_arb_ = tex_bus;
231	    for (uint32_t s = 0; s < sockets_per_cluster; ++s) {
232	      for (uint32_t c = 0; c < cores_per_socket_; ++c) {
233	        uint32_t cid = s * cores_per_socket_ + c;
234	        auto sfu = sockets_.at(s)->core(c)->sfu_unit();
235	        sfu->tex_req_out.bind(&tex_bus->ReqIn.at(cid));
236	        tex_bus->RspOut.at(cid).bind(&sfu->tex_rsp_in);
237	      }
238	    }
239	    tex_bus->ReqOut.at(0).bind(&tex_core_->tex_req_in.at(0));
240	    tex_core_->tex_rsp_out.at(0).bind(&tex_bus->RspIn.at(0));
241	#endif
242	
243	#if defined(VX_CFG_EXT_DXA_ENABLE) || defined(VX_CFG_EXT_TEX_ENABLE) || defined(VX_CFG_EXT_OM_ENABLE) || defined(VX_CFG_EXT_RASTER_ENABLE) || defined(VX_CFG_EXT_RTU_ENABLE)
244	    // L2 arb outputs → l2cache (after all rows are bound).
245	    for (uint32_t i = 0; i < VX_CFG_L2_NUM_REQS; ++i) {
246	      l2arb->ReqOut.at(i).bind(&l2cache_->core_req_in.at(i));
247	      l2cache_->core_rsp_out.at(i).bind(&l2arb->RspIn.at(i));
248	    }
249	#endif
250	
251	#ifdef VX_CFG_EXT_OM_ENABLE
252	    // ── Cluster-shared OM engine + ocache ───────────────────────────────
253	    snprintf(sname, 100, "%s-om-core", name.c_str());
254	    om_core_ = OmCore::Create(sname, simobject_);
255	
256	    // ocache: write-through TLM Cache, config from VX_config.toml [ocache] section.
257	    snprintf(sname, 100, "%s-ocache", name.c_str());
258	    constexpr uint32_t kOcacheLineSize = VX_CFG_MEM_BLOCK_SIZE;
259	    constexpr uint32_t kOcacheWordSize = 4;
260	    constexpr uint32_t kOcacheNumReqs  = VX_CFG_OCACHE_NUM_BANKS;
261	    constexpr uint32_t kOcacheMemPorts = 1;
262	    auto ocache = Cache::Create(sname, Cache::Config{
263	      false,                        // bypass
264	      log2ceil(VX_CFG_OCACHE_SIZE),        // C
265	      log2ceil(kOcacheLineSize),    // L
266	      log2ceil(kOcacheLineSize),    // S (no sectoring)
267	      log2ceil(kOcacheWordSize),    // W
268	      log2ceil(VX_CFG_OCACHE_NUM_WAYS),    // A
269	      log2ceil(VX_CFG_OCACHE_NUM_BANKS),   // B
270	      VX_CFG_XLEN,                         // address bits
271	      kOcacheNumReqs,               // request size
272	      kOcacheMemPorts,              // memory ports
273	      false,                        // write-back (write-through)
274	      true,                         // write response (OM holds its same-pixel
275	                                    // R-M-W interlock until writes COMMIT)
276	      VX_CFG_OCACHE_MSHR_SIZE,             // mshr size
277	      2,                            // pipeline latency
278	      uint8_t(VX_CFG_L2_REPL_POLICY),      // replacement policy
279	      false,                        // is_llc (OCACHE is auxiliary, not LLC)
280	    });
281	    ocache_ = ocache;
282	
283	    // om_core ↔ ocache (per-port).
284	    for (uint32_t i = 0; i < kOcacheNumReqs; ++i) {
285	      om_core_->ocache_req_out.at(i).bind(&ocache->core_req_in.at(i));
286	      ocache->core_rsp_out.at(i).bind(&om_core_->ocache_rsp_in.at(i));
287	    }
288	
289	    // ocache memory side → l2arb. Row index is sockets + DXA + TEX (if those are present).
290	    constexpr uint32_t kOmRow = 1 + VX_CFG_EXT_DXA_ENABLED + VX_CFG_EXT_TEX_ENABLED;
291	    for (uint32_t i = 0; i < kOcacheMemPorts; ++i) {
292	      ocache->mem_req_out.at(i).bind(&l2arb->ReqIn.at(kL2Rows * i + kOmRow));
293	      l2arb->RspOut.at(kL2Rows * i + kOmRow).bind(&ocache->mem_rsp_in.at(i));
294	    }
295	
296	    // Per-core SFU.om_req_out (OmUnit decodes onto it) → OmCore::om_req_in[cid].
297	    // OM has no return value — no rsp channel back to SfuUnit.
298	    for (uint32_t s = 0; s < sockets_per_cluster; ++s) {
299	      for (uint32_t c = 0; c < cores_per_socket_; ++c) {
300	        uint32_t cid = s * cores_per_socket_ + c;
301	        auto sfu = sockets_.at(s)->core(c)->sfu_unit();
302	        sfu->om_req_out.bind(&om_core_->om_req_in.at(cid));
303	      }
304	    }
305	#endif
306	
307	#ifdef VX_CFG_EXT_RASTER_ENABLE
308	    // ── Cluster-shared RASTER engine + rcache ───────────────────────────
309	    snprintf(sname, 100, "%s-raster-core", name.c_str());
310	    raster_core_ = RasterCore::Create(sname, simobject_);
311	
312	    // rcache: read-only TLM Cache, config from VX_config.toml [rcache] section.
313	    snprintf(sname, 100, "%s-rcache", name.c_str());
314	    constexpr uint32_t kRcacheLineSize = VX_CFG_MEM_BLOCK_SIZE;
315	    constexpr uint32_t kRcacheWordSize = 4;
316	    constexpr uint32_t kRcacheNumReqs  = VX_CFG_RCACHE_NUM_BANKS;
317	    constexpr uint32_t kRcacheMemPorts = 1;
318	    auto rcache = Cache::Create(sname, Cache::Config{
319	      false,                        // bypass
320	      log2ceil(VX_CFG_RCACHE_SIZE),        // C
321	      log2ceil(kRcacheLineSize),    // L
322	      log2ceil(kRcacheLineSize),    // S (no sectoring)
323	      log2ceil(kRcacheWordSize),    // W
324	      log2ceil(VX_CFG_RCACHE_NUM_WAYS),    // A
325	      log2ceil(VX_CFG_RCACHE_NUM_BANKS),   // B
326	      VX_CFG_XLEN,                         // address bits
327	      kRcacheNumReqs,               // request size
328	      kRcacheMemPorts,              // memory ports
329	      false,                        // write-back (read-only)
330	      false,                        // write response
331	      VX_CFG_RCACHE_MSHR_SIZE,             // mshr size
332	      2,                            // pipeline latency
333	      uint8_t(VX_CFG_L2_REPL_POLICY),      // replacement policy
334	      false,                        // is_llc (RCACHE is auxiliary, not LLC)
335	    });
336	    rcache_ = rcache;
337	
338	    // raster_core ↔ rcache (per-port).
339	    for (uint32_t i = 0; i < kRcacheNumReqs; ++i) {
340	      raster_core_->rcache_req_out.at(i).bind(&rcache->core_req_in.at(i));
341	      rcache->core_rsp_out.at(i).bind(&raster_core_->rcache_rsp_in.at(i));
342	    }
343	
344	    // rcache memory side → l2arb.
345	    constexpr uint32_t kRasterRow = 1 + VX_CFG_EXT_DXA_ENABLED
346	                                      + VX_CFG_EXT_TEX_ENABLED
347	                                      + VX_CFG_EXT_OM_ENABLED;
348	    for (uint32_t i = 0; i < kRcacheMemPorts; ++i) {
349	      rcache->mem_req_out.at(i).bind(&l2arb->ReqIn.at(kL2Rows * i + kRasterRow));
350	      l2arb->RspOut.at(kL2Rows * i + kRasterRow).bind(&rcache->mem_rsp_in.at(i));
351	    }
352	
353	    // Cluster-level RasterBus arbiter: NUM_CORES_PER_CLUSTER inputs (one per
354	    // SfuUnit) → 1 lane (kNumRasterLanes=1).
355	    snprintf(sname, 100, "%s-raster-bus", name.c_str());
356	    uint32_t cores_per_cluster_r = sockets_per_cluster * cores_per_socket_;
357	    auto raster_bus = RasterBusArbiter::Create(sname, ArbiterType::RoundRobin,
358	                                               cores_per_cluster_r, 1);
359	    raster_bus_arb_ = raster_bus;
360	    for (uint32_t s = 0; s < sockets_per_cluster; ++s) {
361	      for (uint32_t c = 0; c < cores_per_socket_; ++c) {
362	        uint32_t cid = s * cores_per_socket_ + c;
363	        auto sfu = sockets_.at(s)->core(c)->sfu_unit();
364	        sfu->raster_req_out.bind(&raster_bus->ReqIn.at(cid));
365	        raster_bus->RspOut.at(cid).bind(&sfu->raster_rsp_in);
366	      }
367	    }
368	    raster_bus->ReqOut.at(0).bind(&raster_core_->raster_req_in.at(0));
369	    raster_core_->raster_rsp_out.at(0).bind(&raster_bus->RspIn.at(0));
370	#endif
371	
372	#ifdef VX_CFG_EXT_RTU_ENABLE
373	    // ── Cluster-shared RTU engine + rtcache (§8.10) ─────────────────────
374	    snprintf(sname, 100, "%s-rtu-core", name.c_str());
375	    rtu_core_ = RtuCore::Create(sname, simobject_);
376	
377	    // rtcache: RTU-private read-only `Cache` instance, mirror of
378	    // rcache for the raster path. Sits between RtuCore and the L2
379	    // arb so cross-ray BVH-node reuse (root + upper internals) hits
380	    // in L1 instead of thrashing L2. Sizing comes from VX_config.toml
381	    // [rtcache] section.
382	    snprintf(sname, 100, "%s-rtcache", name.c_str());
383	    constexpr uint32_t kRtcacheLineSize = VX_CFG_MEM_BLOCK_SIZE;
384	    constexpr uint32_t kRtcacheWordSize = 4;
385	    // num_inputs = NUM_RTU_BLOCKS so each RtuCore memory port gets
386	    // its own cache input lane. The cache's internal bank crossbar
387	    // arbitrates these inputs onto VX_CFG_RTCACHE_NUM_BANKS banks
388	    // (default 1, single-bank funnel).
389	    constexpr uint32_t kRtcacheNumInputs = VX_CFG_NUM_RTU_BLOCKS;
390	    constexpr uint32_t kRtcacheMemPorts  = 1;
391	    auto rtcache = Cache::Create(sname, Cache::Config{
392	      false,                              // bypass
393	      log2ceil(VX_CFG_RTCACHE_SIZE),      // C
394	      log2ceil(kRtcacheLineSize),         // L
395	      log2ceil(kRtcacheLineSize),         // S (no sectoring)
396	      log2ceil(kRtcacheWordSize),         // W
397	      log2ceil(VX_CFG_RTCACHE_NUM_WAYS),  // A
398	      log2ceil(VX_CFG_RTCACHE_NUM_BANKS), // B
399	      VX_CFG_XLEN,                        // address bits
400	      kRtcacheNumInputs,                  // num_inputs (1 per RTU port)
401	      kRtcacheMemPorts,                   // memory ports
402	      false,                              // write-back (read-only)
403	      false,                              // write response
404	      VX_CFG_RTCACHE_MSHR_SIZE,           // mshr size
405	      2,                                  // pipeline latency
406	      uint8_t(VX_CFG_L2_REPL_POLICY),     // replacement policy
407	      false,                              // is_llc
408	    });
409	    rtcache_ = rtcache;
410	
411	    // RtuCore ↔ rtcache (per memory port).
412	    uint32_t kRtuMemPorts = rtu_core_->dcache_req_out.size();
413	    for (uint32_t i = 0; i < kRtuMemPorts; ++i) {
414	      rtu_core_->dcache_req_out.at(i).bind(&rtcache->core_req_in.at(i));
415	      rtcache->core_rsp_out.at(i).bind(&rtu_core_->dcache_rsp_in.at(i));
416	    }
417	
418	    // rtcache memory side → l2arb at the RTU row.
419	    constexpr uint32_t kRtuRow = 1 + VX_CFG_EXT_DXA_ENABLED
420	                                   + VX_CFG_EXT_TEX_ENABLED
421	                                   + VX_CFG_EXT_OM_ENABLED
422	                                   + VX_CFG_EXT_RASTER_ENABLED;
423	    for (uint32_t i = 0; i < kRtcacheMemPorts; ++i) {
424	      rtcache->mem_req_out.at(i).bind(&l2arb->ReqIn.at(kL2Rows * i + kRtuRow));
425	      l2arb->RspOut.at(kL2Rows * i + kRtuRow).bind(&rtcache->mem_rsp_in.at(i));
426	    }
427	
428	    // Cluster-level RtuBus arbiter: NUM_CORES_PER_CLUSTER inputs (one per
429	    // SfuUnit) → 1 RTU-core lane.
430	    snprintf(sname, 100, "%s-rtu-bus", name.c_str());
431	    uint32_t rtu_cores_per_cluster = sockets_per_cluster * cores_per_socket_;
432	    auto rtu_bus = RtuBusArbiter::Create(sname, ArbiterType::RoundRobin,
433	                                         rtu_cores_per_cluster, 1);
434	    rtu_bus_arb_ = rtu_bus;
435	    for (uint32_t s = 0; s < sockets_per_cluster; ++s) {
436	      for (uint32_t c = 0; c < cores_per_socket_; ++c) {
437	        uint32_t cid = s * cores_per_socket_ + c;
438	        auto sfu = sockets_.at(s)->core(c)->sfu_unit();
439	        sfu->rtu_req_out.bind(&rtu_bus->ReqIn.at(cid));
440	        rtu_bus->RspOut.at(cid).bind(&sfu->rtu_rsp_in);
441	        // §8.6 async ray pool: give each SfuUnit a direct pointer to
442	        // the cluster's RtuCore so its RtuUnit can call
443	        // allocate_slot() / free_slot() without going through the bus.
444	        sfu->set_rtu_core(rtu_core_.get());
445	      }
446	    }
447	    rtu_bus->ReqOut.at(0).bind(&rtu_core_->rtu_req_in.at(0));
448	    rtu_core_->rtu_rsp_out.at(0).bind(&rtu_bus->RspIn.at(0));
449	    (void)rtu_cores_per_cluster;
450	#endif
451	  }
