476	  void global_barrier_arrive(uint32_t bar_id, uint32_t count, uint32_t core_id) {
477	    auto bar_index = bar_id % gbarriers_.size();
478	    auto& gbar = gbarriers_.at(bar_index);
479	
480	    auto sockets_per_cluster = sockets_.size();
481	    auto cores_per_socket = cores_per_socket_;
482	
483	    uint32_t cores_per_cluster = sockets_per_cluster * cores_per_socket;
484	    uint32_t local_core_id = core_id % cores_per_cluster;
485	
486	    // set core arrival bit
487	    gbar.mask.set(local_core_id);
488	
489	    DT(4, "*** Global barrier arrive: cluster #" << simobject_->id() << ", core #" << core_id << " at barrier #" << bar_id << ", arrived=" << gbar.mask.count());
490	
491	    if (gbar.mask.count() == (size_t)count) {
492	      // resume all suspended cores
493	      for (uint32_t s = 0; s < sockets_per_cluster; ++s) {
494	        for (uint32_t c = 0; c < cores_per_socket; ++c) {
495	          uint32_t i = s * cores_per_socket + c;
496	          if (gbar.mask.test(i)) {
497	            sockets_.at(s)->global_barrier_resume(bar_id, c);
498	          }
499	        }
500	      }
501	      // reset mask and advance phase
502	      gbar.mask.reset();
503	    }
504	  }
