531	  int dcr_write(uint32_t addr, uint32_t value) {
532	#ifdef VX_CFG_EXT_DXA_ENABLE
533	    if (addr >= VX_DCR_DXA_STATE_BEGIN && addr < VX_DCR_DXA_STATE_END) {
534	      return dxa_core_->dcr_write(addr, value);
535	    }
536	#endif
537	#ifdef VX_CFG_EXT_TEX_ENABLE
538	    if (addr >= VX_DCR_TEX_STATE_BEGIN && addr < VX_DCR_TEX_STATE_END) {
539	      return tex_core_->dcr_write(addr, value);
540	    }
541	#endif
542	#ifdef VX_CFG_EXT_OM_ENABLE
543	    if (addr >= VX_DCR_OM_STATE_BEGIN && addr < VX_DCR_OM_STATE_END) {
544	#ifdef VX_CFG_EXT_RASTER_ENABLE
545	      // The depth buffer is shared with the raster early-Z stage; let it snoop
546	      // the depth config (zbuf addr/pitch, func, early-Z gate).
547	      raster_core_->om_dcr_snoop(addr, value);
548	#endif
549	      return om_core_->dcr_write(addr, value);
550	    }
551	#endif
552	#ifdef VX_CFG_EXT_RASTER_ENABLE
553	    // RASTER_FRAG_* (fragment-shader dispatch descriptor): capture the
554	    // entry/param halves and latch the assembled 64-bit values into RasterCore
555	    // (descriptor only — the frame is armed by the delegated launch's
556	    // frame_kick, not by these writes). Do NOT forward these to dcr_write —
557	    // that path calls reset_load_state(), which is undesirable for a
558	    // descriptor that only names the FS to launch.
559	    if (addr == VX_DCR_RASTER_FRAG_ENTRY_LO) {
560	      frag_entry_ = (frag_entry_ & ~uint64_t(0xffffffff)) | value;
561	      return 0;
562	    }
563	    if (addr == VX_DCR_RASTER_FRAG_ENTRY_HI) {
564	      frag_entry_ = (frag_entry_ & uint64_t(0xffffffff)) | (uint64_t(value) << 32);
565	      return 0;
566	    }
567	    if (addr == VX_DCR_RASTER_FRAG_PARAM_LO) {
568	      frag_param_ = (frag_param_ & ~uint64_t(0xffffffff)) | value;
569	      return 0;
570	    }
571	    if (addr == VX_DCR_RASTER_FRAG_PARAM_HI) {
572	      frag_param_ = (frag_param_ & uint64_t(0xffffffff)) | (uint64_t(value) << 32);
573	      raster_core_->set_frag_descriptor(frag_entry_, frag_param_);
574	      return 0;
575	    }
576	    if (addr >= VX_DCR_RASTER_STATE_BEGIN && addr < VX_DCR_RASTER_STATE_END) {
577	      return raster_core_->dcr_write(addr, value);
578	    }
579	#endif
580	    for (auto& socket : sockets_) {
581	      int ret = socket->dcr_write(addr, value);
582	      if (ret != 0)
583	        return ret;
584	    }
585	    return 0;
586	  }
